package com.smarthub.plus;
import android.content.Context;
import android.graphics.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.json.*;
/** On-demand English-name PNG catalogue. No bundled pictures, keys, or private server. */
final class EnglishChannelLogos {
 static final String ROOT="https://raw.githubusercontent.com/tv-logo/tv-logos/main/countries/";
 private static final Map<String,String> COUNTRIES=new HashMap<>();
 static{String[] data={"US:united-states","GB:united-kingdom","CA:canada","AU:australia","NZ:new-zealand","IE:ireland","IN:india","SG:singapore","HK:hong-kong","ZA:south-africa","PH:philippines","CZ:czechia","SK:slovakia","PL:poland","RO:romania","FR:france","DE:germany","IT:italy","ES:spain","NL:netherlands","BE:belgium","SE:sweden","NO:norway","DK:denmark","FI:finland","PT:portugal","GR:greece","CH:switzerland","AT:austria","HU:hungary","TR:turkey","AE:united-arab-emirates","IL:israel","LB:lebanon","BR:brazil","MX:mexico","AR:argentina","CL:chile","CO:world-latin-america","RU:russia","UA:ukraine"};for(String row:data){String[] pair=row.split(":");COUNTRIES.put(pair[0],pair[1]);}}
 static String slug(String name){return java.text.Normalizer.normalize(name,java.text.Normalizer.Form.NFKD).replaceAll("\\p{M}+","").replaceFirst("(?i)\\s+(?:SD|HD|FHD|UHD|4K)\\s*$","").replace("&"," and ").replace("+"," plus ").replaceAll("([A-Za-z])([0-9])","$1-$2").toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","-").replaceAll("^-|-$","");}
 static String url(String name,String country){String code=country.toUpperCase(Locale.ROOT),folder=COUNTRIES.get(code),base=slug(name);if(folder==null||!base.matches(".*[a-z].*")||base.length()>120)return "";return ROOT+folder+"/"+base+"-"+(code.equals("GB")?"uk":code.toLowerCase(Locale.ROOT))+".png";}
 static Bitmap fetch(Context c,String name,String country,String nativeId)throws Exception{String code=COUNTRIES.containsKey(country.toUpperCase(Locale.ROOT))?country.toUpperCase(Locale.ROOT):"US";LinkedHashSet<String> markets=new LinkedHashSet<>(Arrays.asList(code,"US","GB"));for(String market:markets){String address=url(name,market);if(address.isEmpty())continue;try{Bitmap bitmap=decode(c,address);if(bitmap!=null){remember(c,nativeId,address);return bitmap;}}catch(Exception unavailable){}if(market.equals(code)){String found=find(c,name,market);if(!found.isEmpty())try{Bitmap bitmap=decode(c,found);if(bitmap!=null){remember(c,nativeId,found);return bitmap;}}catch(Exception unavailable){}}}return null;}
 private static String find(Context c,String name,String code){try{String folder=COUNTRIES.get(code);File dir=new File(c.getCacheDir(),"english-logo-index");dir.mkdirs();File file=new File(dir,code+".json");JSONArray rows=null;if(file.isFile()&&System.currentTimeMillis()-file.lastModified()<24*3600000L)try(InputStream in=new FileInputStream(file)){rows=new JSONArray(PlaylistRepository.readBounded(in));}if(rows==null){rows=new JSONArray(HubHttp.get("https://api.github.com/repos/tv-logo/tv-logos/contents/countries/"+folder+"?ref=main",3*1024*1024));try(FileOutputStream out=new FileOutputStream(file)){out.write(rows.toString().getBytes(StandardCharsets.UTF_8));}}String wanted=ChannelCatalogue.normalized(slug(name)),suffix="-"+(code.equals("GB")?"uk":code.toLowerCase(Locale.ROOT))+".png";for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null)continue;String filename=row.optString("name");if(!filename.endsWith(suffix))continue;String base=filename.substring(0,filename.length()-suffix.length()).replaceFirst("-hz$","");if(!ChannelCatalogue.normalized(base).equals(wanted))continue;String address=row.optString("download_url");if(address.startsWith(ROOT+folder+"/")&&address.endsWith(".png"))return address;}}catch(Exception unavailable){}return "";}
 private static Bitmap decode(Context c,String address)throws Exception{byte[] data=ArtworkCache.fetch(c,new URL(address),2*1024*1024);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,o);if(o.outWidth<=0||o.outHeight<=0||o.outWidth>6000||o.outHeight>6000)return null;o.inSampleSize=1;while(o.outWidth/o.inSampleSize>1024||o.outHeight/o.inSampleSize>1024)o.inSampleSize*=2;o.inJustDecodeBounds=false;return BitmapFactory.decodeByteArray(data,0,data.length,o);}
 private static void remember(Context c,String id,String url){c.getSharedPreferences("smarthub",0).edit().putString("online_logo_url:"+id,url).putString("online_logo_attribution:"+id,"tv-logo/tv-logos · personal use · channel trademarks belong to their owners").putString("online_logo_page:"+id,"https://github.com/tv-logo/tv-logos").apply();}
}
